 * Describe the JSON type of a value the way pointer error messages do.
 *
 * @param {unknown} value the value to describe
 * @returns {string} 'null', 'string', 'number', 'boolean' or the JS typeof
 */
export function describeType(value) {
  if (value === null) return 'null';
  return typeof value;
}

